import{_ as a,c as e,o as i,ah as n}from"./chunks/framework.DE7iKuik.js";const g=JSON.parse('{"title":"MySQL 主从同步","description":"利用 Docker 部署 MySQL，进行主从 同步","frontmatter":{"title":"MySQL 主从同步","createTime":"2023/11/23 18:12:25","permalink":"/article/mysql-master-slave/","tags":["MySQL"],"description":"利用 Docker 部署 MySQL，进行主从 同步","lastUpdated":"2026-01-22","link":"/posts/mysql-master-slave","layout":"doc","prev":{"text":"Windows 删除文件夹内所有 node_modules","link":"/posts/windows-remove-node-modules"},"next":{"text":"MySQL 分时间段查询数据","link":"/posts/mysql-time-period-select"}},"headers":[],"params":{"pkg":"mysql-master-slave"},"relativePath":"posts/mysql-master-slave.md","filePath":"posts/[pkg].md"}'),l={name:"posts/mysql-master-slave.md"};function t(p,s,c,o,d,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h3 id="docker容器" tabindex="-1">Docker容器 <a class="header-anchor" href="#docker容器" aria-label="Permalink to “Docker容器”">​</a></h3><ul><li>Master(主)</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker run -d --name mysql-master -p 3306:3306 -e MYSQL_ROOT_PASSWORD=123456 mysql</span></span></code></pre></div><ul><li>Slave(从)：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker run -d --name mysql-slave -p 3307:3306 -e MYSQL_ROOT_PASSWORD=123456 mysql</span></span></code></pre></div><blockquote><p><code>docker ps</code> 查看容器</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CONTAINER ID   IMAGE     COMMAND                  CREATED          STATUS          PORTS                                                  NAMES</span></span>
<span class="line"><span>be93bbd53052   mysql     &quot;docker-entrypoint.s…&quot;   6 seconds ago    Up 5 seconds    33060/tcp, 0.0.0.0:3307-&gt;3306/tcp, :::3307-&gt;3306/tcp   mysql-slave</span></span>
<span class="line"><span>029572d3cd75   mysql     &quot;docker-entrypoint.s…&quot;   13 seconds ago   Up 10 seconds   0.0.0.0:3306-&gt;3306/tcp, :::3306-&gt;3306/tcp, 33060/tcp   mysql-master</span></span></code></pre></div><h3 id="master主数据库配置" tabindex="-1">Master主数据库配置 <a class="header-anchor" href="#master主数据库配置" aria-label="Permalink to “Master主数据库配置”">​</a></h3><ul><li>进入容器</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker exec -it mysql-master /bin/bash</span></span></code></pre></div><ul><li>更新 <code>apt-get</code> 安装 <code>vim</code> ( <code>mysql</code> 镜像默认没有 <code>vim</code>,需要自己安装)</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update</span></span>
<span class="line"><span>apt-get install -y vim</span></span></code></pre></div><ul><li>添加以下配置 <code>/etc/mysql/my.cnf</code></li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vim /etc/mysql/my.cnf</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[mysqld]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 同一局域网内注意要唯一</span></span>
<span class="line"><span>server-id=100</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 开启二进制日志功能，可以随便取</span></span>
<span class="line"><span>log-bin=mysql-bin</span></span></code></pre></div><blockquote><p>修改配置后需要重启 <code>mysql</code>, 因为使用的 <code>docker</code>，后面直接重启容器</p></blockquote><ul><li>进入数据库</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql -u root  -p</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入密码：123456</span></span></code></pre></div><ul><li>创建 <code>Mysql</code> 用户</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 创建用户</span></span>
<span class="line"><span>CREATE USER &#39;slave&#39;@&#39;%&#39; IDENTIFIED WITH mysql_native_password BY &#39;123456&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 添加 REPLICATION SLAVE 和 REPLICATION CLIENT 权限</span></span>
<span class="line"><span>GRANT REPLICATION SLAVE, REPLICATION CLIENT ON *.* TO &#39;slave&#39;@&#39;%&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 更新</span></span>
<span class="line"><span>FLUSH PRIVILEGES;</span></span></code></pre></div><ul><li>获取主库信息</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show master status;</span></span></code></pre></div><blockquote><p>结果如下，其中的 <code>File</code>、<code>Position</code>需要记录下来，在从库配置是需要用到</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+---------------+----------+--------------+------------------+-------------------+</span></span>
<span class="line"><span>| File          | Position | Binlog_Do_DB | Binlog_Ignore_DB | Executed_Gtid_Set |</span></span>
<span class="line"><span>+---------------+----------+--------------+------------------+-------------------+</span></span>
<span class="line"><span>| binlog.000001 |      1516 |              |                  |                   |</span></span>
<span class="line"><span>+---------------+----------+--------------+------------------+-------------------+</span></span>
<span class="line"><span>1 row in set (0.00 sec)</span></span></code></pre></div><ul><li><code>exit;</code> 退出数据库，<code>exit;</code> 退出容器，重启容器</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker restart mysql-master</span></span></code></pre></div><h3 id="slave从数据库配置" tabindex="-1">Slave从数据库配置 <a class="header-anchor" href="#slave从数据库配置" aria-label="Permalink to “Slave从数据库配置”">​</a></h3><ul><li>进入容器</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker exec -it mysql-slave /bin/bash</span></span></code></pre></div><ul><li>更新 <code>apt-get</code> 安装 <code>vim</code> ( <code>mysql</code> 镜像默认没有 <code>vim</code>,需要自己安装)</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update</span></span>
<span class="line"><span>apt-get install -y vim</span></span></code></pre></div><ul><li>添加配置 <code>/etc/mysql/my.cnf</code></li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[mysqld]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 设置server_id,注意要唯一</span></span>
<span class="line"><span>server-id=101</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 开启二进制日志功能，以备Slave作为其它Slave的Master时使用</span></span>
<span class="line"><span>log-bin=mysql-slave-bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// relay_log配置中继日志</span></span>
<span class="line"><span>relay_log=mysql-relay-bin</span></span></code></pre></div><blockquote><p>修改配置后需要重启 <code>mysql</code>, 因为使用的 <code>docker</code>，后面直接重启容器</p></blockquote><ul><li>进入数据库</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql -u root  -p</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入密码：123456</span></span></code></pre></div><ul><li>链接Master(主)和Slave(从)</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>change master to master_host=&#39;192.168.33.141&#39;, master_user=&#39;slave&#39;, master_password=&#39;123456&#39;, master_port=3306, master_log_file=&#39;mysql-bin.000001&#39;, master_log_pos= 1516, master_connect_retry=30;</span></span></code></pre></div><blockquote><p>命令说明：</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>master_host        		Master的IP地址,这里我直接使用docker宿主机IP，也可以使用容器IP</span></span>
<span class="line"><span>master_port   			Master的端口号</span></span>
<span class="line"><span>master_user				用于数据同步的用户</span></span>
<span class="line"><span>master_password			用于同步的用户的密码</span></span>
<span class="line"><span>master_log_file			指定 Slave 从哪个日志文件开始复制数据，即上文中提到的 File 字段的值</span></span>
<span class="line"><span>master_log_pos			从哪个 Position 开始读，即上文中提到的 Position 字段的值</span></span>
<span class="line"><span>master_connect_retry	如果连接失败，重试的时间间隔，单位是秒，默认是60秒</span></span></code></pre></div><ul><li>开启主从同步</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>start slave;</span></span></code></pre></div><ul><li>查看状态</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show slave status \\G;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Slave_IO_Running: Yes</span></span>
<span class="line"><span>Slave_SQL_Running: Yes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Last_IO_Errno: </span></span>
<span class="line"><span>Last_SQL_Errno:</span></span></code></pre></div><blockquote><p><code>Slave_IO_Running</code> 和 <code>Slave_SQL_Running</code> 默认 <code>No</code>，如果都为 <code>Yes</code>，表示主从同步配置成功，否则失败，可以查看 <code>Last_IO_Errno</code> 和 <code>Last_SQL_Errno</code> 报错内容。</p></blockquote>`,46)])])}const k=a(l,[["render",t]]);export{g as __pageData,k as default};
